	orddm16 36670, xhl
	jr CtrlPanel_PopRetFA

LABEL_FC7974:
	orddm16 36674, xhl
	jr CtrlPanel_PopRetFA

LABEL_FC797A:
	orddm16 36678, xhl

CtrlPanel_PopRetFA:
	pop_werp 0xFA
	ret

