CtrlPanel_SetIndicatorLED:
	push_werp 0xFA
	ld c, a
	and c, 0xF0
	ldfr_berp C, 0xFB
	and a, 0xF
	extz wa
	call CtrlPanel_LookupIndicatorEntry
